-- Section 113 — Reformation & Monarchy Band 5 Sprint
-- Creates the first genuine Band 5 ceiling for reformation_monarchy.
-- Prior to this migration reformation_monarchy had zero Band 5 questions (50 active across Bands 1-4).
--
-- 20 questions: target_grade=9, difficulty_band=5, domain=reformation_monarchy, is_active=true
-- Distribution: Reformation & Luther(4) + Monarki/Absolutisme/Magt(4) + Religionskrige/Etik(4)
--               + Historiografi(4) + Moderne Relevans(4)
-- Uses dollar-quoting ($$) throughout to avoid apostrophe escaping issues.

-- ─── BAND 5 · REFORMATION & LUTHER (4 questions) ─────────────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Var Reformationen primært et religiøst oprør — eller var dens succes betinget af politiske og økonomiske faktorer?","options":["Begge dimensioner er nødvendige: Luthers teologiske indsigter (nåde alene, skrift alene) udgjorde den religiøse drivkraft men reformationens spredning og overlevelse skyldtes i høj grad tyske fyrsters politiske og dynastiske interesser samt borgerskabets modstand mod pavelig skatteindkrævning. Luther uden de tyske fyrster var sandsynligvis endt som Jan Hus","Reformationen var udelukkende religiøs — politiske og økonomiske faktorer spillede ingen selvstændig rolle i dens spredning og konsolidering","Reformationen var udelukkende politisk og dynastisk — Luthers teologi var blot et ideologisk dække for verdslige magtinteresser","Reformationens succes skyldtes udelukkende trykpressen der spredde Luthers ideer — ingen andre faktorer var afgørende"],"correct":"Begge dimensioner er nødvendige: Luthers teologiske indsigter (nåde alene, skrift alene) udgjorde den religiøse drivkraft men reformationens spredning og overlevelse skyldtes i høj grad tyske fyrsters politiske og dynastiske interesser samt borgerskabets modstand mod pavelig skatteindkrævning. Luther uden de tyske fyrster var sandsynligvis endt som Jan Hus","accepted_answers":["Begge dimensioner er nødvendige: Luthers teologiske indsigter (nåde alene, skrift alene) udgjorde den religiøse drivkraft men reformationens spredning og overlevelse skyldtes i høj grad tyske fyrsters politiske og dynastiske interesser samt borgerskabets modstand mod pavelig skatteindkrævning. Luther uden de tyske fyrster var sandsynligvis endt som Jan Hus"],"review_text":"Luthers teologiske gennembrud var reelt og selvstændigt: sola gratia, sola fide og sola scriptura var et fundamentalt opgør med den sakramentale nådeøkonomi der gav kirken sin intermediarfunktion. Men Jan Hus havde formuleret lignende kritikker et århundrede tidligere og endt på bålet i Konstanz 1415. Hvad var anderledes? De tyske kurfyrsters beskyttelse af Luther på Wartburg (1521), deres modstand mod Habsburgernes religiøse uniformitetspolitik og borgerskabets systematiske modstand mod afladshandel og pavelig skatteindkrævning. Augsburgske Religionsfred (1555) og cujus regio ejus religio-princippet institutionaliserede fyrsternes religiøse autonomi — et politisk resultat med religiøst indhold. Multi-kausal analyse er uomgængelig: religiøs innovation eksisterede, politisk opportunitet muliggjorde dens institutionalisering."}$$::jsonb,
  'mc','short',$${"concepts":["Luther","sola scriptura","tyske fyrster","Jan Hus","multi-kausalitet","Augsburgske Religionsfred"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er den afgørende forskel på Erasmus' og Luthers reformprogram — og hvad forklarer at de to venner endte som principielle modstandere?","options":["Erasmus ville reformere kirken indefra via humanistisk kritik og sproglig tekstkritik uden at bryde med Roms autoritet. Luther brød fundamentalt med kirkens autoritet via sola scriptura. Skillelinjen gik ved fri vilje-debatten (1524-25): Erasmus fastholdt at mennesket har fri vilje til at medvirke til frelse — Luther afviste dette som kætteri der undergraver nådens suverænitet","Erasmus og Luther var enige om alle teologiske spørgsmål og deres strid var rent personlig og politisk uden principiel dimension","Luther ville reformere indefra og Erasmus bryde med Rom — historiografien har fejlagtigt byttet om på rollerne","Erasmus var katolsk apologet uden egentlig reformvilje og betegnelsen 'humanistisk reformator' er fejlplaceret på ham"],"correct":"Erasmus ville reformere kirken indefra via humanistisk kritik og sproglig tekstkritik uden at bryde med Roms autoritet. Luther brød fundamentalt med kirkens autoritet via sola scriptura. Skillelinjen gik ved fri vilje-debatten (1524-25): Erasmus fastholdt at mennesket har fri vilje til at medvirke til frelse — Luther afviste dette som kætteri der undergraver nådens suverænitet","accepted_answers":["Erasmus ville reformere kirken indefra via humanistisk kritik og sproglig tekstkritik uden at bryde med Roms autoritet. Luther brød fundamentalt med kirkens autoritet via sola scriptura. Skillelinjen gik ved fri vilje-debatten (1524-25): Erasmus fastholdt at mennesket har fri vilje til at medvirke til frelse — Luther afviste dette som kætteri der undergraver nådens suverænitet"],"review_text":"Erasmus og Luther delte et udgangspunkt: kirken var korrumperet og i behov for reform. Men de divergerede afgørende i metode og teologi. Erasmus (De libero arbitrio, 1524) forsvarede kirkens tradition og menneskets begrænsede frihed til at samvirke med Guds nåde — en position forenelig med kirkens sakramentale system. Luthers svar (De servo arbitrio, 1525) er det mest kompromisløse teologiske skrift han nogensinde skrev: menneskeviljens ufrihed er ikke et perifert spørgsmål men selve fundamentet for sola gratia. Humanistisk kritik (Erasmus' Dårskabers pris, Novum Testamentum) åbnede for reformationen intellektuelt men Erasmus trak grænsen ved skisma. Jan Huizinga kaldte Erasmus for 'den mand der syggjorde sin verden uden at kurere den' — en karakterisering der illustrerer præcis skillelinjen: reformation indefra versus reformation der nødvendigvis sprænger institutionen."}$$::jsonb,
  'mc','short',$${"concepts":["Erasmus","Luther","fri vilje","sola gratia","humanisme","reformation indefra"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad kendetegner den danske Reformation (1536) — og hvad adskiller den fra den tyske reformationsproces?","options":["Den danske Reformation var en statslig reformation ovenfra: Christian III udnyttede grevefejdens kaos til at indføre lutheranismen, beslaglægge kirkegods og underordne kirken under kongemagten. I modsætning til den tyske reformation der begyndte med Luthers folkelige appel og splittede det politiske landskab, var den danske reformation primært et magtpolitisk projekt med religiøs begrundelse — kirken blev et statsapparat","Den danske Reformation var identisk med den tyske og fulgte samme proces med folkelig religiøs bevægelse som den primære drivkraft og fyrsternes rolle var sekundær","Den danske Reformation var en ren religiøs bevægelse uden statslig intervention og kongemagten spillede ingen afgørende rolle i reformationens gennemførelse","Den danske Reformation fandt sted i 1517 simultant med Luthers 95 teser og er dermed historisk den første nationale Reformation"],"correct":"Den danske Reformation var en statslig reformation ovenfra: Christian III udnyttede grevefejdens kaos til at indføre lutheranismen, beslaglægge kirkegods og underordne kirken under kongemagten. I modsætning til den tyske reformation der begyndte med Luthers folkelige appel og splittede det politiske landskab, var den danske reformation primært et magtpolitisk projekt med religiøs begrundelse — kirken blev et statsapparat","accepted_answers":["Den danske Reformation var en statslig reformation ovenfra: Christian III udnyttede grevefejdens kaos til at indføre lutheranismen, beslaglægge kirkegods og underordne kirken under kongemagten. I modsætning til den tyske reformation der begyndte med Luthers folkelige appel og splittede det politiske landskab, var den danske reformation primært et magtpolitisk projekt med religiøs begrundelse — kirken blev et statsapparat"],"review_text":"Christian III (konge fra 1534) gennemførte Reformationen i 1536 som en centraliseret statsreform: Odense-mødet og Ribebrevene codificerede den lutherske statskirke. De syv katolske biskopper blev arresteret og kirkegodset — estimeret til en tredjedel af Kongerigets faste ejendom — overgik til Kronen. Kirken tabte sin selvstændige juridiske og økonomiske position og blev et kongeligt embedsapparat med præster som statslønnet personale. Det teologiske indhold (Bugenhagen redigerede kirkens ordinans) var luthersk-ortodokst men den institutionelle form var konsekvent etatistisk. Sammenligningen med den tyske reformation er analytisk vigtig: i Sachsen, Brandenburg og Württemberg var det fyrster der beskyttede og institutionaliserede en allerede eksisterende folkelig bevægelse — i Danmark var den folkelige dimension svagere og statsinstitutionaliseringen hurtigere og mere fuldstændig. Konsekvensen er synlig i dag: Folkekirken er stadig en statskirke."}$$::jsonb,
  'mc','short',$${"concepts":["dansk reformation","Christian III","statskirke","grevefejden","kirkegods","ovenfra-reformation"],"misconception_type":"false_equivalence","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad var trykpressens afgørende rolle i Reformationen — og hvad er den relevante parallel til sociale mediers rolle i dag?","options":["Trykpressen demokratiserede adgangen til religiøs tekst og argument: Luthers skrifter nåede hundredtusinder inden kirken kunne reagere effektivt. Parallellen til sociale medier er analytisk frugtbar men ikke perfekt: begge teknologier omgik etablerede informationsfiltre (kirkens/redaktionel gatekeeping) og muliggjorde hurtig spredning af udfordrende synspunkter. Men begge skabte også misinformation og radikalisering — Bundskrifterne og bondekrigens propaganda er parallellen til falske nyheder og ekstremistisk mobilisering","Trykpressen var irrelevant for Reformationens succes — mundtlig forkyndelse i kirkerum var den eneste effektive kommunikationsform i 1500-tallets Europa","Trykpressen og sociale medier er fuldstændig analoge og der er ingen meningsfulde historiske forskelle mellem de to situationer","Trykpressen styrkede primært den katolske kirkes position ved at muliggøre bedre distribution af pavelige dekreter og apologetisk litteratur"],"correct":"Trykpressen demokratiserede adgangen til religiøs tekst og argument: Luthers skrifter nåede hundredtusinder inden kirken kunne reagere effektivt. Parallellen til sociale medier er analytisk frugtbar men ikke perfekt: begge teknologier omgik etablerede informationsfiltre (kirkens/redaktionel gatekeeping) og muliggjorde hurtig spredning af udfordrende synspunkter. Men begge skabte også misinformation og radikalisering — Bundskrifterne og bondekrigens propaganda er parallellen til falske nyheder og ekstremistisk mobilisering","accepted_answers":["Trykpressen demokratiserede adgangen til religiøs tekst og argument: Luthers skrifter nåede hundredtusinder inden kirken kunne reagere effektivt. Parallellen til sociale medier er analytisk frugtbar men ikke perfekt: begge teknologier omgik etablerede informationsfiltre (kirkens/redaktionel gatekeeping) og muliggjorde hurtig spredning af udfordrende synspunkter. Men begge skabte også misinformation og radikalisering — Bundskrifterne og bondekrigens propaganda er parallellen til falske nyheder og ekstremistisk mobilisering"],"review_text":"Andrew Pettegree (Brand Luther, 2015) viser at Luther var den første 'mediepersonlighed' i moderne forstand: han forstod trykpressens muligheder og producerede skrifter i en stil og på et sprog (tysk folkesprog) der appellerede til lægfolk. Inden 1520 var Luthers skrifter trykt i hundredtusinder af eksemplarer — et hastigheds- og udbredelsesniveau der var historisk enestående. Kirken reagerede langsomt fordi dens administrative og kommunikative infrastruktur ikke var tilpasset mediets hurtighed. Elizabeth Eisenstein (The Printing Press as an Agent of Change, 1980) argumenterer at trykpressen ikke blot spredte Reformationen men muliggjorde standardisering af religiøs tekst der var umulig i håndskriftskulturen. Parallellen til sociale medier er metodologisk interessant men begrænset: 1500-tallets trykpresse krævede materielle ressourcer og literacy, sociale medier er næsten omkostningsfri og literacy-uafhængig. Begge disruptions skapte dog radikalisering som ikke-intenderet konsekvens."}$$::jsonb,
  'mc','short',$${"concepts":["trykpresse","Luther","mediedisruption","sociale medier","Pettegree","Eisenstein"],"misconception_type":"overgeneralization","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

-- ─── BAND 5 · MONARKI, ABSOLUTISME & MAGT (4 questions) ──────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er den filosofiske begrundelse for absolutismen — og hvad er det stærkeste argument imod den?","options":["Absolutismens begrundelse (Bodin, Bossuet): kongen er Guds stedfortræder eller den rationelle indehaver af alle statsmagter der alene kan sikre orden og fred — suverænitet er udelelig og ukrænkelig. Det stærkeste argument imod (Locke, Montesquieu): absolutisme kan ikke korrigere sig selv — der er ingen mekanisme til at fjerne en tyrannisk suveræn uden revolution, og koncentreret magt korrumperer systematisk","Absolutismen er udelukkende en praktisk styreform uden filosofisk fundament og bør kun vurderes på effektivitet","Absolutismen er altid og i alle former identisk med tyranni — der er ingen legitime varianter eller nuancer","Guddommelig ret er den eneste gyldige begrundelse for suverænitet og alle sekulære begrundelser er sekundære og underordnede"],"correct":"Absolutismens begrundelse (Bodin, Bossuet): kongen er Guds stedfortræder eller den rationelle indehaver af alle statsmagter der alene kan sikre orden og fred — suverænitet er udelelig og ukrænkelig. Det stærkeste argument imod (Locke, Montesquieu): absolutisme kan ikke korrigere sig selv — der er ingen mekanisme til at fjerne en tyrannisk suveræn uden revolution, og koncentreret magt korrumperer systematisk","accepted_answers":["Absolutismens begrundelse (Bodin, Bossuet): kongen er Guds stedfortræder eller den rationelle indehaver af alle statsmagter der alene kan sikre orden og fred — suverænitet er udelelig og ukrænkelig. Det stærkeste argument imod (Locke, Montesquieu): absolutisme kan ikke korrigere sig selv — der er ingen mekanisme til at fjerne en tyrannisk suveræn uden revolution, og koncentreret magt korrumperer systematisk"],"review_text":"Jean Bodins Six livres de la République (1576) formulerede den første systematiske suverænitetsteori: suveræn er den der har eneretten til at lovgive uden at være bundet af andres love. Bossuets Politique tirée des propres paroles de l'Écriture sainte (1709) tilføjede den teologiske legitimation: kongen er ansvarlig over for Gud alene — et argument der placerer al verdslig kritik som utilbørlig indblanding i det guddommelige. Hobbes' Leviathan (1651) leverede en sekulær udgave: kun en absolut suveræn kan forhindre at naturstilstandens alles krig mod alle genopstår. Det strukturelle problem som Locke identificerede: suverænens legitimitet hviler på om den beskytter borgernes naturlige rettigheder — og der er ingen neutral instans til at afgøre om den svigter. Absolutismens logiske lukkethed er dens akilleshæl: den kan ikke institutionelt korrigere sig selv og producerer dermed enten velfungerende patrimonial stat eller uhæmmet tyranni."}$$::jsonb,
  'mc','short',$${"concepts":["absolutisme","Bodin","Bossuet","guddommelig ret","suverænitet","Locke"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad adskiller Montesquieus analytiske distinktion mellem monarki og despotisme — og hvad er dens relevans for vurderingen af konkrete enevælderegimer?","options":["Montesquieu: monarki er et enestyre begrænset af love, traditioner og mellemliggende institutioner (adel, parlament, kirke) der fungerer som buffere mod tyranni. Despotiet er enestyre uden juridiske skranker der styrer via frygt alene. Distinktionen er analytisk vigtig: Frederik d. Store og Katarina d. Store opererede inden for institutionelle rammer — de er monarkier, ikke despotier i Montesquieus analyse","Montesquieu mente at monarki og despotisme er identiske styreformer og distinktionen er blot en retorisk forskel uden analytisk substans","Alle monarkier er nødvendigvis despotier fordi en enkelt persons herredømme ikke kan institutionelt kontrolleres tilstrækkeligt","Montesquieus distinktion er et historisk kuriosum uden relevans for analysen af moderne autoritære regimer og styreformer"],"correct":"Montesquieu: monarki er et enestyre begrænset af love, traditioner og mellemliggende institutioner (adel, parlament, kirke) der fungerer som buffere mod tyranni. Despotiet er enestyre uden juridiske skranker der styrer via frygt alene. Distinktionen er analytisk vigtig: Frederik d. Store og Katarina d. Store opererede inden for institutionelle rammer — de er monarkier, ikke despotier i Montesquieus analyse","accepted_answers":["Montesquieu: monarki er et enestyre begrænset af love, traditioner og mellemliggende institutioner (adel, parlament, kirke) der fungerer som buffere mod tyranni. Despotiet er enestyre uden juridiske skranker der styrer via frygt alene. Distinktionen er analytisk vigtig: Frederik d. Store og Katarina d. Store opererede inden for institutionelle rammer — de er monarkier, ikke despotier i Montesquieus analyse"],"review_text":"Montesquieus De l'Esprit des Lois (1748) klassificerede styreformer efter princip snarere end antal styrende: republikkens princip er dyd, monarkiets er ære og despotiets er frygt. Et monarki kan bevæge sig mod despotisme hvis de mellemliggende institutioner svækkes — det er netop Ludvig XIVs Versailles-politik der neutraliserede adelen som politisk modmagt ved at koncentrere den ved hoffet og gøre den afhængig af kongens nåde. Den analytiske distinktion er fortsat relevant: politiske systemer kan graduelt bevæge sig langs et spektrum. Nutidig applikation: Singapores Law-styrede autoritarisme adskiller sig fra Nordkoreas totalitære frygtregime præcis ved at have retsstatselementer der begrænser vilkårlighed selv om demokratisk legitimitet mangler. Montesquieus institutionelle blik er mere nuanceret end den binære demokrati/diktatur-distinktion."}$$::jsonb,
  'mc','short',$${"concepts":["Montesquieu","monarki vs despotisme","mellemliggende institutioner","Versailles","institutionel analyse","frygt vs ære"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad var adelens rolle i absolutismens styresystem — og hvad er paradokset i forholdet mellem enevælde og aristokrati?","options":["Paradokset: absolutisme centraliserede magten hos kongen og svækkede adelens politiske selvstændighed, men adelen forblev et nødvendigt administrativt og militært redskab. Ludvig XIVs Versailles-strategi er det klareste eksempel: ved at tvinge adelen til hoffet og konkurrere om hofgratifikationer neutraliserede han den som politisk trussel — og bevarede dens sociale og symbolske funktion som aristokrati","Adelen var altid en loyal og konfliktfri støtte for absolutismen og konflikten mellem kongemagt og adel er en historiografisk konstruktion der intet belæg har","Absolutismen eliminerede fuldstændigt adelens rolle og erstattede den konsekvent med et upersonligt meritokratisk bureaukrati","Adelen og absolutismen var strukturelt uforenelige og enhver enevælde måtte nødvendigvis afskaffe aristokratiet for at konsolidere sin magt"],"correct":"Paradokset: absolutisme centraliserede magten hos kongen og svækkede adelens politiske selvstændighed, men adelen forblev et nødvendigt administrativt og militært redskab. Ludvig XIVs Versailles-strategi er det klareste eksempel: ved at tvinge adelen til hoffet og konkurrere om hofgratifikationer neutraliserede han den som politisk trussel — og bevarede dens sociale og symbolske funktion som aristokrati","accepted_answers":["Paradokset: absolutisme centraliserede magten hos kongen og svækkede adelens politiske selvstændighed, men adelen forblev et nødvendigt administrativt og militært redskab. Ludvig XIVs Versailles-strategi er det klareste eksempel: ved at tvinge adelen til hoffet og konkurrere om hofgratifikationer neutraliserede han den som politisk trussel — og bevarede dens sociale og symbolske funktion som aristokrati"],"review_text":"Norbert Elias' The Court Society (1969) er den klassiske analyse af Versailles som et disciplineringsprojekt. Ludvig XIV genopbyggede Versailles og transformerede det til et obligatorisk opholdssted for de store adelsslægter: at blive væk fra hoffet var et tegn på kongeligt mishag og mistede netværksmuligheder. Den politiske konsekvens var systematisk: adelige der tilbragte deres tid i Versailles' rituelle etikette kunne ikke administrere deres provinsielle godser som selvstændige magtcentre. De blev statspensionstager snarere end provinsfyrster. Skatteindkrævning og lokal administration overgik til intendanterne — royale embedsmænd der ikke var adelige og dermed lettere at kontrollere. Paradokset er komplet: absolutismen bevarede aristokratiets sociale hierarki mens den demonterede dets politiske funktion. Den franske adelstand i 1789 var politisk neutraliseret men socialt privilegeret — en ustabil kombination der bidrog til revolutionens katastrofale dynamik."}$$::jsonb,
  'mc','short',$${"concepts":["adel og absolutisme","Versailles","Ludvig XIV","Elias","hofsamfund","intendanter"],"misconception_type":"causal_inversion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvordan styrkede Reformationen den verdslige statsmagts position — og hvad er den langsigtede politiske konsekvens?","options":["Reformationen styrkede statsmagt på to strukturelle måder: (1) protestantiske fyrster overtog kirkegods og kirkelig organisation og underordnede kirken under statens kontrol via cujus regio ejus religio-princippet, og (2) pavens universelle autoritet over europæiske monarker brød endeligt sammen — suverænitetsprincippet internationaliseredes som statsret. Den langsigtede konsekvens: den moderne suveræne nationalstat er delvist et protestantisk projekt","Reformationen svækkede statsmagten ved at skabe permanent religiøs splittelse der underminerede statens politiske og territoriale enhed","Reformationen havde ingen effekt på statsmagtens struktur — den var udelukkende et indre kirkeligt anliggende om teologi og gudstjeneste","Cujus regio ejus religio-princippet er et udelukkende juridisk begreb uden reelle politiske konsekvenser for magtbalancen"],"correct":"Reformationen styrkede statsmagt på to strukturelle måder: (1) protestantiske fyrster overtog kirkegods og kirkelig organisation og underordnede kirken under statens kontrol via cujus regio ejus religio-princippet, og (2) pavens universelle autoritet over europæiske monarker brød endeligt sammen — suverænitetsprincippet internationaliseredes som statsret. Den langsigtede konsekvens: den moderne suveræne nationalstat er delvist et protestantisk projekt","accepted_answers":["Reformationen styrkede statsmagt på to strukturelle måder: (1) protestantiske fyrster overtog kirkegods og kirkelig organisation og underordnede kirken under statens kontrol via cujus regio ejus religio-princippet, og (2) pavens universelle autoritet over europæiske monarker brød endeligt sammen — suverænitetsprincippet internationaliseredes som statsret. Den langsigtede konsekvens: den moderne suveræne nationalstat er delvist et protestantisk projekt"],"review_text":"Philip Gorskis The Disciplinary Revolution (2003) og Charles Tillys statsbyggeanalyser viser at Reformationen og den europæiske statskonsolidering er sammenvævede processer. I England konfiskerede Heinrich VIII klostrenes godser (Dissolution of the Monasteries 1536-41) og placerede kirken under kongeligt overhoved (Act of Supremacy 1534). I Skandinavien overtog Christian III og Gustaf Vasa kirkegods som finansierede det tidligmoderne bureaukrati. Cujus regio ejus religio (Augsburg 1555) legaliserede fyrsternes religiøse suverænitet over deres territorier — en de facto anerkendelse af at statsgrænser definerer retsanliggender inkl. religiøse. Westfalerfredens (1648) ikke-indblanding-princip er den fulde institutionalisering: staten er suveræn over alle forhold inden for dens grænser. Max Webers argument i den protestantiske etik er relevant her: lutheranismens konsekvens for statsdisciplin og statsbureaukrati er mindst ligeså vigtig som dens påvirkning på kapitalisme."}$$::jsonb,
  'mc','short',$${"concepts":["Reformationen og statsmagt","cujus regio ejus religio","kirkegods","suverænitet","Westfalen","statsbyggeri"],"misconception_type":"scope_confusion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

-- ─── BAND 5 · RELIGIONSKRIGE & ETIK (4 questions) ────────────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Var de europæiske religionskrige i 1500-1600-tallet primært religiøse — eller var religion et ideologisk dække for politiske og dynastiske konflikter?","options":["Begge dimensioner er uadskillelige: religion og politik var ikke adskilte kategorier i 1500-tallets Europa — en fyrstes tro definerede hans alliancer, hans undersåtters juridiske status og hans dynastiske strategier. Trediveårskrigen begyndte som en bøhmisk religionskrig og endte som en dynastisk og geopolitisk konflikt om tysk magtbalance — begge dimensioner var reelle og gensidigt forstærkende","Religionskrigene var udelukkende religiøse — politiske og dynastiske faktorer var analytisk irrelevante for at forstå dem korrekt","Religionskrigene var udelukkende politiske og dynastiske — religion var kun et retorisk skjul for verdslige magtinteresser uden reel motiverende kraft","Det er historisk metodisk umuligt at adskille religiøse og politiske motiver i perioden og spørgsmålet er analytisk uproduktivt"],"correct":"Begge dimensioner er uadskillelige: religion og politik var ikke adskilte kategorier i 1500-tallets Europa — en fyrstes tro definerede hans alliancer, hans undersåtters juridiske status og hans dynastiske strategier. Trediveårskrigen begyndte som en bøhmisk religionskrig og endte som en dynastisk og geopolitisk konflikt om tysk magtbalance — begge dimensioner var reelle og gensidigt forstærkende","accepted_answers":["Begge dimensioner er uadskillelige: religion og politik var ikke adskilte kategorier i 1500-tallets Europa — en fyrstes tro definerede hans alliancer, hans undersåtters juridiske status og hans dynastiske strategier. Trediveårskrigen begyndte som en bøhmisk religionskrig og endte som en dynastisk og geopolitisk konflikt om tysk magtbalance — begge dimensioner var reelle og gensidigt forstærkende"],"review_text":"Trediveårskrigen (1618-48) er det vigtigste eksempel. Den begyndte med Fensterstyrtningen i Prag (1618) som en religiøs konflikt om bøhmisk protestantismens rettigheder. Den transformerede sig gradvist: Frankrig — et katolsk monarki — støttede protestantiske tyske fyrster og Sverige mod det katolske Habsburg-imperium fordi Habsburgernes dominans var en geopolitisk trussel uanset religionspolitikken. Kardinal Richelieu er emblematisk: han styrede den mest katolske konges udenrigspolitik ud fra realpolitiske hensyn der underordnede religiøs solidaritet statsinteressen. Geoffrey Parkers The Thirty Years' War (1984) dokumenterer at krigsmotivationer var komplekst sammensatte. Den analytisk vigtige pointe: i et samfund hvor religion er identisk med politisk loyalitet, er det meningsløst at adskille de to som uafhængige årsagskategorier — religionen er politisk og politikken er religiøs."}$$::jsonb,
  'mc','short',$${"concepts":["religionskrige","Trediveårskrigen","Richelieu","religion og politik","realpolitik","Parker"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad var Westfalerfreden (1648) et brud med — og hvad er dens principielle betydning for international orden?","options":["Westfalerfreden var et brud med idéen om religiøs universalisme som grundlag for politisk orden: fred blev ikke baseret på religiøs enhed men på statssuverænitetsprincippet — staters ret til ikke-indblanding i hinandens indre anliggender inkl. religion. Dette er en skelsættende institutionalisering af statssuverænitet som internationalt ordensprincip der erstatter den middelalderlige kirkelige universalisme","Westfalerfreden var en ren militær aftale om territoriale grænser uden principielle konsekvenser for international ret og orden","Westfalerfreden indførte fuld religionsfrihed for alle europæiske borgere og afsluttede enhver form for statslig religionskontrol og forfølgelse","Westfalerfreden bekræftede og styrkede pavens autoritet over europæiske monarkers religiøse politikker og kirkelige organisation"],"correct":"Westfalerfreden var et brud med idéen om religiøs universalisme som grundlag for politisk orden: fred blev ikke baseret på religiøs enhed men på statssuverænitetsprincippet — staters ret til ikke-indblanding i hinandens indre anliggender inkl. religion. Dette er en skelsættende institutionalisering af statssuverænitet som internationalt ordensprincip der erstatter den middelalderlige kirkelige universalisme","accepted_answers":["Westfalerfreden var et brud med idéen om religiøs universalisme som grundlag for politisk orden: fred blev ikke baseret på religiøs enhed men på statssuverænitetsprincippet — staters ret til ikke-indblanding i hinandens indre anliggender inkl. religion. Dette er en skelsættende institutionalisering af statssuverænitet som internationalt ordensprincip der erstatter den middelalderlige kirkelige universalisme"],"review_text":"Westfalerfredens Osnabrück-traktat og Münster-traktat (1648) afsluttede Trediveårskrigen og den spansk-hollandske krig. Princippet om cuius regio ejus religio fra Augsburg (1555) blev revideret til også at inkludere calvinisterne og fastholde en status quo på en 1624-baseline der forhindrede yderligere tvangsrekatolisering. Det principielle brud er metodologisk vigtigt: den internationale orden hvilede ikke længere på en fælles religiøs autoritet (paven) men på stats-til-stats-relationer baseret på gensidig anerkendelse af suverænitet. Leo Gross' klassiske artikel The Peace of Westphalia 1648-1948 identificerede det som grundlag for det moderne internationale system. Kritikere (Krasner, Osiander) hævder at Westfalerfredens-myten er en anakronistisk konstruktion fra senere — men systemskiftet i praksis er reelt: den internationale orden orienterede sig derefter om suveræne stater snarere end religiøs universalisme."}$$::jsonb,
  'mc','short',$${"concepts":["Westfalerfreden","statssuverænitet","ikke-indblanding","religiøs universalisme","international orden","Gross"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad afslørede Bartholomæusnatten (1572) om forholdet mellem religiøs overbevisning og moralsk ansvar?","options":["Bartholomæusnatten afslørede at religiøs overbevisning kan bruges til at suspendere normale etiske begrænsninger: massakren på 5.000-30.000 huguenotter blev retfærdiggjort af religiøs nødvendighed og kongelig autorisation. Etisk analyse: de religiøse begrundelser var ikke en formildende omstændighed men en forværrende — de muliggjorde systematisk massemord på civile via dehumanisering af den religiøse anden og fraskrivelse af individuelle aktørers ansvar","Bartholomæusnatten er etisk ukritiserbar fordi datidens normer for religiøs konflikthåndtering var anderledes end nutidens og anakronistisk etisk kritik er metodisk illegitimt","Bartholomæusnatten viser at religion altid og nødvendigvis producerer vold — etisk fordømmelse af den konkrete begivenhed er den eneste mulige reaktion","Massakren var udelukkende et politisk magtspil og religion spillede ingen reel rolle i motivationen bag begivenhederne"],"correct":"Bartholomæusnatten afslørede at religiøs overbevisning kan bruges til at suspendere normale etiske begrænsninger: massakren på 5.000-30.000 huguenotter blev retfærdiggjort af religiøs nødvendighed og kongelig autorisation. Etisk analyse: de religiøse begrundelser var ikke en formildende omstændighed men en forværrende — de muliggjorde systematisk massemord på civile via dehumanisering af den religiøse anden og fraskrivelse af individuelle aktørers ansvar","accepted_answers":["Bartholomæusnatten afslørede at religiøs overbevisning kan bruges til at suspendere normale etiske begrænsninger: massakren på 5.000-30.000 huguenotter blev retfærdiggjort af religiøs nødvendighed og kongelig autorisation. Etisk analyse: de religiøse begrundelser var ikke en formildende omstændighed men en forværrende — de muliggjorde systematisk massemord på civile via dehumanisering af den religiøse anden og fraskrivelse af individuelle aktørers ansvar"],"review_text":"Bartholomæusnatten startede natten mellem den 23. og 24. august 1572 i Paris med kongehusmedlemmers beslutning om at eliminere protestantiske ledere forsamlet til brylluppet mellem Henrik af Navarra og Margarete af Valois. Det udvidede sig til folkemord der varede i uger i Paris og provinserne. Katarina de Medici og Karl IX autoriterede den indledende fase. Ansvarsfraskrivelsen via religiøs nødvendighedslære er etisk central: deltagerne handlede på autoritet (kongeligt mandat og religiøs legitimering) og som del af en kollektiv handling der anonymiserede individuelle handlinger. Parallellen til Hannah Arendts Eichmann-analyse er metodologisk relevant: 'ondskabens banalitet' er ikke et 1900-tals fænomen men en strukturel egenskab ved situationer hvor institutionel autoritet og ideologisk legitimering befrier individer fra moralsk ansvar. Etisk vurdering kræver ikke anakronisme — Montaigne og andre samtidige fordømte massakren eksplicit."}$$::jsonb,
  'mc','short',$${"concepts":["Bartholomæusnatten","religionsvold","etisk ansvar","autoritetslydighed","Arendt","huguenotter"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad var Ediktet af Nantes (1598) — og hvad viser dets tilbagekaldelse (1685) om tolerancens strukturelle skrøbelighed?","options":["Ediktet gav huguenotter religionsfrihed og borgerlige rettigheder — en pragmatisk toleranceløsning drevet af statslig stabilitetshensyn snarere end principiel samvittighedsfrihed. Tilbagekaldelsen af Ludvig XIV viser at statslig tolerance er betinget og reversibel: da kongen vurderede at statsenheden kræver religiøs uniformitet, ophævede han ediktet. Tolerance som politisk pragmatisme er strukturelt skrøbeligere end tolerance som grundrettighedsgaranti","Ediktet af Nantes indførte fuldstændig og varig religionsfrihed i Frankrig og tilbagekaldelsen var et historisk tilfælde uden principiel læringsværdi","Ediktet var udelukkende en militær aftale om vaabenstilstand uden religiøst indhold og tolerancedimensionen er en historiografisk overfortolkning","Tolerancens tilbagekaldelse beviser universelt at religiøs tolerance aldrig er holdbar og altid vil kollapse til religiøs forfølgelse"],"correct":"Ediktet gav huguenotter religionsfrihed og borgerlige rettigheder — en pragmatisk toleranceløsning drevet af statslig stabilitetshensyn snarere end principiel samvittighedsfrihed. Tilbagekaldelsen af Ludvig XIV viser at statslig tolerance er betinget og reversibel: da kongen vurderede at statsenheden kræver religiøs uniformitet, ophævede han ediktet. Tolerance som politisk pragmatisme er strukturelt skrøbeligere end tolerance som grundrettighedsgaranti","accepted_answers":["Ediktet gav huguenotter religionsfrihed og borgerlige rettigheder — en pragmatisk toleranceløsning drevet af statslig stabilitetshensyn snarere end principiel samvittighedsfrihed. Tilbagekaldelsen af Ludvig XIV viser at statslig tolerance er betinget og reversibel: da kongen vurderede at statsenheden kræver religiøs uniformitet, ophævede han ediktet. Tolerance som politisk pragmatisme er strukturelt skrøbeligere end tolerance som grundrettighedsgaranti"],"review_text":"Henrik IV's Edikt af Nantes (april 1598) afsluttede de franske religionskrige ved at give huguenotternes omkring 200.000 en særlig retsstatus: fri religionsudøvelse i visse byer og regioner, adgang til alle embeder og særlige retssale (chambres mi-parties). Det var et pragmatisk kompromis — Henrik var selv convert fra protestantisme — drevet af krigsudmattelse og statens behov for fred. Ludvig XIV revokerede ediktet med Fontainebleau-ediktet (1685): 200.000 huguenotter emigrerede til England, Holland og Preussen — et hjerneflugt-fænomen der styrkede Frankrigs konkurrenter. Konsekvensen var economisk og diplomatisk katastrofal. Den principielle lektion: tolerance der kun hviler på statslig pragmatisme er sårbar over for skiftende statsinteresse-vurderinger. Tolerance der er forankret som rettighed (ECHR artikel 9) er strukturelt mere stabil. Denne lektion er direkte relevant for nutidens debatter om religiøse mindretals rettigheder i stater med varierende grad af rettighedsgaranti."}$$::jsonb,
  'mc','short',$${"concepts":["Ediktet af Nantes","Ludvig XIV","tilbagekaldelse","pragmatisk tolerance","rettighedsgaranti","huguenotter"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

-- ─── BAND 5 · HISTORIOGRAFI (4 questions) ────────────────────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er konfessionaliseringstesens centrale påstand — og hvad er dens historiografiske konsekvens for forståelsen af Reformationens langsigtede effekter?","options":["Konfessionaliseringstesen (Reinhard, Schilling): Reformationen var ikke et afsluttet brud i 1517 men en langtrukken disciplineringsproces 1550-1650 hvor katolske, lutherske og calvinistiske konfessioner alle parallelt opbyggede statskirker, standardiserede tro og adfærd og brugte religion til statslig disciplinering af befolkningerne. Konsekvensen: alle konfessioner deltog i det samme moderniseringsforløb — reformationens resultater er ikke protestantismens privilegium","Konfessionaliseringstesen gælder udelukkende lutheranismen — den katolske kirke gennemgik ingen tilsvarende disciplineringsproces under eller efter Tridentinerkoncilet","Historiografien er samlet enig om at Reformationen var et afsluttet brud i 1517 og periodiseringsdebatten er akademisk trivialitet","Periodiseringen af Reformationen er udelukkende kronologisk og har ingen analytiske implikationer for forståelsen af dens historiske effekter"],"correct":"Konfessionaliseringstesen (Reinhard, Schilling): Reformationen var ikke et afsluttet brud i 1517 men en langtrukken disciplineringsproces 1550-1650 hvor katolske, lutherske og calvinistiske konfessioner alle parallelt opbyggede statskirker, standardiserede tro og adfærd og brugte religion til statslig disciplinering af befolkningerne. Konsekvensen: alle konfessioner deltog i det samme moderniseringsforløb — reformationens resultater er ikke protestantismens privilegium","accepted_answers":["Konfessionaliseringstesen (Reinhard, Schilling): Reformationen var ikke et afsluttet brud i 1517 men en langtrukken disciplineringsproces 1550-1650 hvor katolske, lutherske og calvinistiske konfessioner alle parallelt opbyggede statskirker, standardiserede tro og adfærd og brugte religion til statslig disciplinering af befolkningerne. Konsekvensen: alle konfessioner deltog i det samme moderniseringsforløb — reformationens resultater er ikke protestantismens privilegium"],"review_text":"Wolfgang Reinhard og Heinz Schillings konfessionaliseringstese (formuleret 1977-84) udfordrede den protestantisk-centrerede reformationshistoriografi. Tesen: 1500-1600-tallets afgørende proces er ikke Reformationens teologiske brud men den parallelle institutionalisering i alle konfessioner af statskirker der disciplinerede befolkningernes liv, tro og adfærd. Tridentinerkoncilet (1545-63) og Jesuitternes uddannelsesprogram producerede en disciplineret katolsk konfession parallelt med den lutherske og den reformerte. Konsekvensen er historiografisk vigtig: Webers tese om protestantismens særlige moderniseringsbidrag relativeres — alle konfessioner bidrog til den bureaukratiske disciplinering der producerede det moderne samfund. Philip Gorskis The Disciplinary Revolution (2003) videreudvikler tesen og viser at Calvins Genève og den hollandske refomerte kirke var særligt effektive disciplineringsinstanser. Tesen er omdiskuteret (Schilling og Reinhard har selv nuanceret den) men dens analytiske bidrag er at flytte fokus fra teologisk indhold til institutionel funktion."}$$::jsonb,
  'mc','short',$${"concepts":["konfessionalisering","Reinhard","Schilling","disciplinering","statskirke","modernisering"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Var Reformationen en folkelig bevægelse nedefra eller en fyrstestyret transformation ovenfra — og hvad viser historieforskningen?","options":["Forskningen viser begge dimensioner på forskellige faser: den tidlige Luther-bevægelse (1517-1525) havde reel folkelig appel — håndværkere, borgerskab og bønder mobiliserede sig aktivt. Men Bondeoprøret (1525) og Luthers fordømmelse af det markerede et brud: Reformationen konsoliderede sig som en fyrstestyret kirkeinstitution ovenfra. Peter Blickle viser at det radikale nedefra-potentiale var reelt men blev kanaliseret og undertrykket","Reformationen var udelukkende en folkelig bevægelse nedefra og fyrsternes rolle var ren opportunistisk parasit på en allerede eksisterende folkelig bevægelse","Reformationen var udelukkende en fyrstestyret transformation ovenfra og folkelig religiøs entusiasme var ideologisk irrelevant og uden selvstændig historisk drivkraft","Bondeoprøret (1525) beviser at den folkelige dimension altid var Reformationens primære og eneste afgørende drivkraft"],"correct":"Forskningen viser begge dimensioner på forskellige faser: den tidlige Luther-bevægelse (1517-1525) havde reel folkelig appel — håndværkere, borgerskab og bønder mobiliserede sig aktivt. Men Bondeoprøret (1525) og Luthers fordømmelse af det markerede et brud: Reformationen konsoliderede sig som en fyrstestyret kirkeinstitution ovenfra. Peter Blickle viser at det radikale nedefra-potentiale var reelt men blev kanaliseret og undertrykket","accepted_answers":["Forskningen viser begge dimensioner på forskellige faser: den tidlige Luther-bevægelse (1517-1525) havde reel folkelig appel — håndværkere, borgerskab og bønder mobiliserede sig aktivt. Men Bondeoprøret (1525) og Luthers fordømmelse af det markerede et brud: Reformationen konsoliderede sig som en fyrstestyret kirkeinstitution ovenfra. Peter Blickle viser at det radikale nedefra-potentiale var reelt men blev kanaliseret og undertrykket"],"review_text":"Peter Blickle (The Revolution of 1525, 1981) og Hans-Jürgen Goertz har argumenteret at den tidlige reformation havde et revolutionært nedefra-potentiale der gik langt ud over Luthers teologiske program: Bundskrifterne (Zwölf Artikel, 1525) formulerede bondestandens krav om ophævelse af livegenskab, frit valg af præster og reducerede afgifter — med direkte inspiration fra lutherske frihedsbegreber. Luthers Gegen die räuberischen und mörderischen Rotten der Bauern (1525) opfordrede fyrsterne til hensynsløst at nedkæmpe bondeoprøret. Det demografiske drab (100.000 bønder dræbt) markerede reformationens elitisering: den teologiske frihed Luther proklamerede overfor paven var ikke ment som social og politisk frihed for bønder. Blickles Gemeindereformation-tese viser at bybefolkningens reformationsopfattelse var bredere demokratisk end luthersk ortodoksi tillod. Reformationens institutionelle konsolidering ovenfra er den historiske sejrherre — men det folkelige potentiale var historisk reelt."}$$::jsonb,
  'mc','short',$${"concepts":["nedefra-reformation","Bondeoprøret","Blickle","Luther og bønder","fyrstereformation","folkelig mobilisering"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Var Modreformationen primært en defensiv reaktion mod protestantismen — eller en selvstændig reformbevægelse med egne interne drivkræfter?","options":["Begge dimensioner er valide: intern katolsk reformbevægelse forud for Luther (Erasmus, spanske mystikere, Oratoriet for guddommelig kærlighed) viser at indre reformimpulser eksisterede selvstændigt. Men Tridentinerkoncilet (1545-63) og Jesuitternes program fik en tydeligt defensiv og anti-protestantisk form under protestantismens pres. At reducere Modreformationen til ren reaktion er historiografisk utilstrækkeligt men den protestantiske udfordring formede afgørende reformens tempo og indhold","Modreformationen var udelukkende en defensiv reaktion mod protestantismen uden nogen selvstændige interne reformdrivkræfter i den katolske kirke","Modreformationen var udelukkende en selvstændig intern reformbevægelse og protestantismens eksistens var helt irrelevant for dens retning og indhold","Modreformationen var et fuldstændigt fiasko der ikke producerede nogen reelle ændringer i den katolske kirkes teologi, struktur eller praksis"],"correct":"Begge dimensioner er valide: intern katolsk reformbevægelse forud for Luther (Erasmus, spanske mystikere, Oratoriet for guddommelig kærlighed) viser at indre reformimpulser eksisterede selvstændigt. Men Tridentinerkoncilet (1545-63) og Jesuitternes program fik en tydeligt defensiv og anti-protestantisk form under protestantismens pres. At reducere Modreformationen til ren reaktion er historiografisk utilstrækkeligt men den protestantiske udfordring formede afgørende reformens tempo og indhold","accepted_answers":["Begge dimensioner er valide: intern katolsk reformbevægelse forud for Luther (Erasmus, spanske mystikere, Oratoriet for guddommelig kærlighed) viser at indre reformimpulser eksisterede selvstændigt. Men Tridentinerkoncilet (1545-63) og Jesuitternes program fik en tydeligt defensiv og anti-protestantisk form under protestantismens pres. At reducere Modreformationen til ren reaktion er historiografisk utilstrækkeligt men den protestantiske udfordring formede afgørende reformens tempo og indhold"],"review_text":"Historiografien har debatteret terminologien: Gegenreformation (ren reaktion) versus Katholische Reform (selvstændig modernisering). Hubert Jedins klassiske skelnen (Geschichte des Konzils von Trient, 1957) fastholdt begge dimensioner som samtidige. Interne impulser: Jiménez de Cisneros' spanske kirkerefrom (1490erne), Oratoriet for guddommelig kærlighed (Genua og Rom, 1490erne), og Ignatius af Loyolas Jesuitterorden (1540) var alle initiativer der forud for eller uafhængig af protestantismen søgte fornyelse. Men Tridentinerkoncilet (1545-63) var direkte udløst af protestantismens udfordring og dens beslutninger om tradition som kilde ved siden af skriften, og bevaringen af den latinske messe var defensivt positionerede. Jesuitternes uddannelsespolitik og missionsprogram var et anti-protestantisk kulturberedskab. Begge dimensioner er historiografisk nødvendige for en fuldstændig analyse."}$$::jsonb,
  'mc','short',$${"concepts":["Modreformationen","Tridentinerkoncilet","Jesuitter","katolsk reform","Jedin","reaktion vs selvstændig reform"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er Webers protestantiske etik-tese — og hvad er de stærkeste empiriske indvendinger mod den?","options":["Weber (Den protestantiske etik og kapitalismens ånd, 1905): calvinistisk prædestinationslære skabte en psykologisk disposition til systematisk asketisk arbejdsdisciplin og akkumulation som tegn på udvælgelse — en mentalitetsstruktur der var den kulturelle forudsætning for moderne kapitalisme. Indvendinger: kapitalisme opstod i katolske byer (Firenze, Antwerpen) forud for calvinismen og Weber overvurderer ideernes selvstændige årsagskraft i forhold til strukturelle og materielle faktorer","Webers tese er empirisk fuldt bekræftet og alle indvendinger mod den er ideologisk motiverede forsvar for katolsk kultur","Weber argumenterede for at protestantisme hæmmede kapitalisme og at katolicisme var kapitalismens åndelige og kulturelle forudsætning","Webers tese er rent sociologisk og har ingen historisk relevans for forståelsen af Reformationens kulturelle og economiske konsekvenser"],"correct":"Weber (Den protestantiske etik og kapitalismens ånd, 1905): calvinistisk prædestinationslære skabte en psykologisk disposition til systematisk asketisk arbejdsdisciplin og akkumulation som tegn på udvælgelse — en mentalitetsstruktur der var den kulturelle forudsætning for moderne kapitalisme. Indvendinger: kapitalisme opstod i katolske byer (Firenze, Antwerpen) forud for calvinismen og Weber overvurderer ideernes selvstændige årsagskraft i forhold til strukturelle og materielle faktorer","accepted_answers":["Weber (Den protestantiske etik og kapitalismens ånd, 1905): calvinistisk prædestinationslære skabte en psykologisk disposition til systematisk asketisk arbejdsdisciplin og akkumulation som tegn på udvælgelse — en mentalitetsstruktur der var den kulturelle forudsætning for moderne kapitalisme. Indvendinger: kapitalisme opstod i katolske byer (Firenze, Antwerpen) forud for calvinismen og Weber overvurderer ideernes selvstændige årsagskraft i forhold til strukturelle og materielle faktorer"],"review_text":"Max Webers Die protestantische Ethik und der Geist des Kapitalismus (1905) er et af socialvidenskabens mest indflydelsesrige og mest omdiskuterede projekter. Tesen: calvinistisk prædestinationslære (ingen kan vide om de er udvalgt til frelse) skabte en intense angst der psykologisk blev håndteret ved systematisk at søge tegn på udvælgelse — succes i kald og erhverv. Den asketiske akkumulation (tjene meget, forbruge lidt) er strukturelt analog til kapitalistisk kapitalakkumulation. Empiriske indvendinger: Firenze og Antwerpen var centre for avanceret handelsmæssig kapitalisme et århundrede forud for calvinismens udbredelse — begge var katolske byer. Werner Sombart (Der moderne Kapitalismus, 1902) argumenterede at jødisk handelskultur var ligeså vigtig. R.H. Tawney (Religion and the Rise of Capitalism, 1926) inverterede kausaliteten: det var kapitalismens succes der ændrede de protestantiske teologers etik — ikke omvendt. Webers metodologiske bidrag er idéhistorisk og mentalitetshistorisk — han adspurgte idéers autonome årsagskraft, men den empiriske basis er sårbar."}$$::jsonb,
  'mc','short',$${"concepts":["Weber","protestantisk etik","kapitalisme","prædestination","Tawney","idéers årsagskraft"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

-- ─── BAND 5 · MODERNE RELEVANS & EVALUERING (4 questions) ────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Er den religiøse tolerance der gradvist opstod efter Reformationskrigene et stabilt principielt fundament — eller et skrøbeligt pragmatisk kompromis?","options":["Historisk er tolerancen primært pragmatisk opstået: den opstod fordi religionskrigene var for destruktive til at fortsætte, ikke fordi en principiel konsensus om samvittighedsfrihed var opnået. Dette forklarer dens strukturelle skrøbelighed: tolerance er robust når den understøttes af principielle rettigheder (ECHR artikel 9) men sårbar som ren statspragmatisme — Ediktet af Nantes' tilbagekaldelse er det historiske bevis","Religiøs tolerance er et stabilt og permanent principielt fundament der er opnået og ikke kan undermineres i moderne demokratier","Religiøs tolerance er aldrig mulig på principielt grundlag — kun magtbalance kan sikre den midlertidigt og pragmatisk","Religiøs tolerance er et nyt fænomen opstået med liberaldemokratiet i det 20. århundrede og Reformationstidens erfaringer er historisk irrelevante for vores forståelse"],"correct":"Historisk er tolerancen primært pragmatisk opstået: den opstod fordi religionskrigene var for destruktive til at fortsætte, ikke fordi en principiel konsensus om samvittighedsfrihed var opnået. Dette forklarer dens strukturelle skrøbelighed: tolerance er robust når den understøttes af principielle rettigheder (ECHR artikel 9) men sårbar som ren statspragmatisme — Ediktet af Nantes' tilbagekaldelse er det historiske bevis","accepted_answers":["Historisk er tolerancen primært pragmatisk opstået: den opstod fordi religionskrigene var for destruktive til at fortsætte, ikke fordi en principiel konsensus om samvittighedsfrihed var opnået. Dette forklarer dens strukturelle skrøbelighed: tolerance er robust når den understøttes af principielle rettigheder (ECHR artikel 9) men sårbar som ren statspragmatisme — Ediktet af Nantes' tilbagekaldelse er det historiske bevis"],"review_text":"Perez Zagorins How the Idea of Religious Toleration Came to the West (2003) dokumenterer at principiel tolerancetænkning (ikke blot pragmatisk tolerance af tvang) gradvist udviklede sig: Sebastian Castellio (1554) formulerede den første principielle toleranceargument direkte mod Calvins henrettelse af Servet. Men den brede statslige tolerance var pragmatisk: Westfalerfredens religiøse kompromis var udtmattelsestolerance. Ediktet af Nantes' tilbagekaldelse (1685) er det klareste historiske bevis for at pragmatisk tolerance er reversibel. Den moderne rettighedsbaserede tolerance (ECHR artikel 9, art. 18 i FN-menneskerettighedserklæringen) er strukturelt stærkere fordi den er forankret som individuel rettighed statens pragmatik ikke kan ophæve uden traktatsforpligtelse. Men selv rettighedsbaseret tolerance er presset: Frankrig og Tyrkiet har juridiske konstruktioner der potentielt begrænser religiøs praksis. Reformationens lektion er fortsat relevant: tolerance kræver institutionel forankring, ikke blot pragmatisk accept."}$$::jsonb,
  'mc','short',$${"concepts":["religionsfrihed","pragmatisk tolerance","ECHR","Ediktet af Nantes","Castellio","rettighedsforankring"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Lagde Reformationen grundlaget for moderne individualisme — og hvad er begrænsningerne ved denne sammenhæng?","options":["Reformationen bidrog til individualismens betingelser: (1) den private bibellæsning og samvittighedens suverænitet over kirkens formidlingsmonopol, og (2) den direkte relation til Gud uden præstelig mellemkomst. Men begrænsningen er strukturel: lutheranisme og calvinisme var intenst kollektivistiske og disciplinerende i praksis — individuel samvittighed erstattede ét autoritetsmonopol (paven) med et andet (bibelen og statskirken), ikke med sekulær individualistisk frihed","Reformationen er den direkte og tilstrækkelige årsag til moderne individualisme uden forbehold eller nuancering","Reformationen forhindrede aktivt individualismens fremvækst og sekulær humanisme er den eneste historiske kilde til moderne individualistisk tænkning","Individualisme er et 1800-tals fænomen opstået uafhængigt af Reformationen og enhver forbindelse er en historiografisk konstruktion"],"correct":"Reformationen bidrog til individualismens betingelser: (1) den private bibellæsning og samvittighedens suverænitet over kirkens formidlingsmonopol, og (2) den direkte relation til Gud uden præstelig mellemkomst. Men begrænsningen er strukturel: lutheranisme og calvinisme var intenst kollektivistiske og disciplinerende i praksis — individuel samvittighed erstattede ét autoritetsmonopol (paven) med et andet (bibelen og statskirken), ikke med sekulær individualistisk frihed","accepted_answers":["Reformationen bidrog til individualismens betingelser: (1) den private bibellæsning og samvittighedens suverænitet over kirkens formidlingsmonopol, og (2) den direkte relation til Gud uden præstelig mellemkomst. Men begrænsningen er strukturel: lutheranisme og calvinisme var intenst kollektivistiske og disciplinerende i praksis — individuel samvittighed erstattede ét autoritetsmonopol (paven) med et andet (bibelen og statskirken), ikke med sekulær individualistisk frihed"],"review_text":"Jacob Burckhardts The Civilization of the Renaissance in Italy (1860) lokaliserede individualismens historiske oprindelse i renæssancen snarere end i reformationen. Charles Taylors Sources of the Self (1989) viser at protestantismens bidrag til moderne identitet er mere ambivalent: den personlige ansvarliggørelse over for Gud og den direkte samvittighedsrelation til den skrevne bibel er et individualiserende moment — men Calvins Genève var et kollektivistisk disciplineringsregime der forfulgte afvigere. Luthers 'Ein feste Burg ist unser Gott' er et fællesskabshymne, ikke en individualistisk bekendelse. Michael Walzers The Revolution of the Saints (1965) viser at calvinistisk puritanisme var et fanatisk kollektivistisk projekt. Det analytisk rigtige svar: Reformationen satte betingelser for individualismens fremvækst (samvittighedens autoritet, bibeltekstens frihed fra kirkens monopolfortolkning) men realiserede ikke individualisme som praktisk frihed — den udsatte den til en oplysningstidens sekulære videreudvikling."}$$::jsonb,
  'mc','short',$${"concepts":["individualisme","Reformationen","samvittighed","Taylor","Calvins Genève","kollektivisme"],"misconception_type":"overgeneralization","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er Reformationens arv for forholdet mellem kirke og stat i Danmark i dag — og hvad er den demokratiske spænding i nutidig statskirkemodel?","options":["Den danske Reformation (1536) skabte en statskirkemodel der fortsat eksisterer: Folkekirken er finansieret via kirkeskat og biskopperne er statsansatte. Dette er en historisk kontinuitet fra Christian III's kirkereform. Den demokratiske spænding: i et multireligiøst samfund er en konfessionel statskirkemodel ikke religionsneutral — det strukturelle privilegium for ét trossamfund er en ulighed der er vanskeligere at retfærdiggøre i et sekulært demokrati end i en luthersk monokultur","Den danske kirkereform i 1536 skabte øjeblikkeligt adskillelse af kirke og stat og Folkekirken i dag er fuldstændig adskilt fra statens institutioner og finansiering","Statskirkemodellen er et neutralt arrangement der ikke favoriserer nogen bestemt religiøs tradition og er demokratisk uproblematisk","Reformationens kirkelige arv er historisk irrelevant for at forstå den nutidige danske kirkepolitik og dens demokratiske implikationer"],"correct":"Den danske Reformation (1536) skabte en statskirkemodel der fortsat eksisterer: Folkekirken er finansieret via kirkeskat og biskopperne er statsansatte. Dette er en historisk kontinuitet fra Christian III's kirkereform. Den demokratiske spænding: i et multireligiøst samfund er en konfessionel statskirkemodel ikke religionsneutral — det strukturelle privilegium for ét trossamfund er en ulighed der er vanskeligere at retfærdiggøre i et sekulært demokrati end i en luthersk monokultur","accepted_answers":["Den danske Reformation (1536) skabte en statskirkemodel der fortsat eksisterer: Folkekirken er finansieret via kirkeskat og biskopperne er statsansatte. Dette er en historisk kontinuitet fra Christian III's kirkereform. Den demokratiske spænding: i et multireligiøst samfund er en konfessionel statskirkemodel ikke religionsneutral — det strukturelle privilegium for ét trossamfund er en ulighed der er vanskeligere at retfærdiggøre i et sekulært demokrati end i en luthersk monokultur"],"review_text":"Den danske grundlov § 4 fastslår at 'Den evangelisk-lutherske kirke er den danske folkekirke og understøttes som sådan af staten.' Folkekirken finansieres via en kirkelig ligning (særlig skat for medlemmer) og statsbevillinger til visse formål. Folkekirkens biskopperne er formelt embedsmænd der udnævnes af kongen (i praksis regeringen). Christian III's Reces af 1536 var det historiske fundament: kirken blev et kongeligt statsapparat. I dag er ca. 73% af danskerne folkekirkens medlemmer men andelen falder støt, og Danmark er etnisk og religiøst mere mangfoldigt end i 1536. Den demokratiske spænding er reel: statslig finansiering af og strukturel favorisering af ét religiøst trossamfund er vanskeligt at forene med neutralitetsprincippet i en multikulturel stat. Sammenlign med Sverige der adskilt kirke og stat i 2000. Den historiske kontinuitet fra Reformationen er direkte synlig i nutidig dansk religionspolitik."}$$::jsonb,
  'mc','short',$${"concepts":["Folkekirken","statskirke","Christian III","grundlov § 4","religiøs ulighed","multireligiøst samfund"],"misconception_type":"causal_inversion","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  $${"question":"Hvad er Reformationens vigtigste bidrag til det moderne pluralistiske samfund — og hvad er de uintenderede destruktive konsekvenser?","options":["Reformationens vigtigste bidrag: den brød det katolske universalitetsmonopol og etablerede principielt at ingen enkelt religiøs autoritetsinstans kan dominere alle borgeres samvittighed — et intellektuelt grundlag for pluralisme. De uintenderede destruktive konsekvenser: religionskrigene producerede mere ødelæggelse end middelalderens religiøse konflikter og tolerancen der opstod var udmattelsestolerancen fra katastrofal destruktion snarere end principiel åbenhed","Reformationen er pluralismens direkte og tilsigtede skaber — reformatorerne planlagde bevidst pluralisme og religionsfrihed som deres politiske mål","Reformationen underminerede alt grundlag for pluralisme ved at skabe permanent religiøs sekterisme og politisk ustabilitet","Pluralisme er et fænomen opstået fuldstændigt uafhængigt af Reformationen og enhver historisk forbindelse er en konstrueret narrativ"],"correct":"Reformationens vigtigste bidrag: den brød det katolske universalitetsmonopol og etablerede principielt at ingen enkelt religiøs autoritetsinstans kan dominere alle borgeres samvittighed — et intellektuelt grundlag for pluralisme. De uintenderede destruktive konsekvenser: religionskrigene producerede mere ødelæggelse end middelalderens religiøse konflikter og tolerancen der opstod var udmattelsestolerancen fra katastrofal destruktion snarere end principiel åbenhed","accepted_answers":["Reformationens vigtigste bidrag: den brød det katolske universalitetsmonopol og etablerede principielt at ingen enkelt religiøs autoritetsinstans kan dominere alle borgeres samvittighed — et intellektuelt grundlag for pluralisme. De uintenderede destruktive konsekvenser: religionskrigene producerede mere ødelæggelse end middelalderens religiøse konflikter og tolerancen der opstod var udmattelsestolerancen fra katastrofal destruktion snarere end principiel åbenhed"],"review_text":"Brad Gregory (The Unintended Reformation, 2012) er den mest ambitiøse analyse af reformationens uintenderede konsekvenser: ved at bryde det katolske universalitetsmonopol uden at erstatte det med en anden autoritativ sandhedsinstans frigjorde Reformationen en pluralisme som Luther, Calvin og Zwingli ville have fordømt. Konsekvensen: ubegrænsede konfessionelle og sekteriske fragmenteringer som ingen reformator ønskede. Stuart Swifts argument i A Secular Age (Taylor, 2007) er analogt: Reformationen er en forudsætning for sekulariseringen men en utilsigtet forudsætning. Den destruktive dimension er empirisk solid: Trediveårskrigen reducerede Centraleuropas befolkning med 25-40% i visse regioner — en demografisk katastrofe der overtrufne pestepidemiernes effekter. Den tolerance der opstod af Westfalen var ikke principielt ønsket af nogen af parterne men produceret af udmattelse og pragmatisk nødvendighed. Reformationens bidrag til pluralismen er real men omvejene var blodige og de reformatorerne selv ville have rystet på hovedet."}$$::jsonb,
  'mc','short',$${"concepts":["pluralisme","Reformationens arv","Brad Gregory","uintenderede konsekvenser","udmattelsestolerance","sekularisering"],"misconception_type":"overgeneralization","cognitive_skill":"synthesis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}$$::jsonb,
  'mc_single',5,'auto',true,'reformation_monarchy',9,5
);
